// Tasty Gallery — Layouts: a saved remote workspace (R-58).
// A remote workspace added from the GUI stays in the sidebar across restarts and when the connection drops.
// Parts: ui_kits/terminal/overlays/remote_row.jsx (popup, marks, menu items, confirm) and chrome.jsx WorkspaceRow.
import React from "react";
import { Spec, Stage, Meta, Note, Do, Dont, Views, View } from "../parts/specimen.jsx";
import { ThemePair } from "../parts/theme-frame.jsx";
import { WorkspaceRow } from "../../ui_kits/terminal/chrome.jsx";
import { RemoteConnectionPopup, RemoteWorkspaceContent, RemoteRailMarks, REMOTE_REASONS, remoteRowTip } from "../../ui_kits/terminal/overlays/remote_row.jsx";

const LANGS = ["en", "ko", "ja", "zh-Hans"];
const cap = { fontFamily: "var(--tasty-font-mono)", fontSize: "var(--tasty-font-size-micro)", color: "var(--tasty-text-muted)" };
const Labelled = ({ label, children }) => (
  <div style={{ display: "flex", flexDirection: "column", gap: "var(--tasty-space-xs)", minWidth: 0 }}>
    <span style={cap}>{label}</span>
    {children}
  </div>
);
const col = (children) => <div style={{ display: "flex", flexDirection: "column", gap: "var(--tasty-space-md)", minWidth: 0 }}>{children}</div>;
const row = (children) => <div style={{ display: "flex", flexWrap: "wrap", gap: "var(--tasty-space-lg)", alignItems: "flex-start" }}>{children}</div>;

const WS = { name: "tasty-core", profile: "host", remote: "tasty-core" };
const Frame = ({ shape, children }) => <RemoteWorkspaceContent shape={shape} width="var(--tasty-remote-row-specimen-width)" height="var(--tasty-remote-row-specimen-height)">{children}</RemoteWorkspaceContent>;
const Pop = (p) => <RemoteConnectionPopup name={WS.name} profile={WS.profile} remote={WS.remote} {...p} />;

// ── 1. Not connected yet: the bare workspace ──
export function RemoteRowEmptySpec() {
  return (
    <Spec id="remote-row-popup-on-the-bare-workspace" title="Not connected yet — the bare workspace and its connection popup"
      when={<>After a restart every saved remote row comes back <b>without tabs, panes or surfaces</b>: its workspace is the bare workspace ground and one popup in its centre. The popup is the <b>only place</b> that says how the row stands: where it points (attach <b>profile</b> and the <b>remote workspace</b> name, both mono, because the local row can be renamed), the state, a reason when it failed, and the one action. Opening the row starts connecting at once, so the first thing you usually see is <b>Connecting…</b>: the button keeps its place, disabled, with a spinner, as the child graph's Reconnect does. A failed attempt leaves the warning glyph, <b>Connection failed</b>, the reason and <b>Connect</b>. When the <b>remote Tasty force-detaches</b> a remote workspace, every saved row that points at it is <b>held</b>: it does not start connecting when shown or opened, or for an agent, until the user connects that row. A row whose own first attempt was cut shows <b>Disconnected</b>, the remote-disconnected body and <b>Connect</b>. A row held only by the mark (another row of the same remote workspace, or any of them after a restart while the mark is saved) shows a body that says the remote Tasty ended this Tasty's connection to that remote workspace: on the bare workspace under <b>Not connected</b> with <b>Connect</b>, and over a last screen it still has under <b>Disconnected</b> with <b>Reconnect</b>. Neither has a warning glyph. The popup is Workspace-scope: it shows only while this workspace is on screen, never takes focus on its own, and has no close button (there is nothing behind it to go back to). Close the row from its menu.</>}>
      <Stage variant="solo" style={{ padding: "var(--tasty-space-lg)", background: "var(--tasty-bg-app)" }}>
        <ThemePair render={() => col(<>
          <Labelled label="connecting — opened by the user, or on screen without a click (a restart, window focus, a neighbour closed)"><Frame><Pop kind="connecting" /></Frame></Labelled>
          <Labelled label="failed — the remote workspace is in use by another client"><Frame><Pop kind="failed" reason="occupied" /></Frame></Labelled>
          <Labelled label="force-detached while connecting, before a screen · Connect"><Frame><Pop kind="server" /></Frame></Labelled>
          <Labelled label="held — another row of the same remote workspace was force-detached, or any of them after a restart · Connect"><Frame><Pop kind="held" /></Frame></Labelled>
          <Labelled label="the user chose Disconnect while it was connecting · held like any user Disconnect · Connect"><Frame><Pop kind="user" /></Frame></Labelled>
          <Labelled label="not connected — the active workspace of a window that is not focused · connects when that window is focused"><Frame><Pop kind="idle" /></Frame></Labelled>
        </>)} />
      </Stage>
      <Views>
        <View name="remote-row-popup-every-reason" label="Failed — every reason · a missing remote workspace is Remote workspace closed">
          {row(REMOTE_REASONS.map((r) => r === "workspace_missing"
            ? <Labelled key={r} label={"reason: " + r + " → closed · Connect disabled"}><Frame><Pop kind="closed" /></Frame></Labelled>
            : <Labelled key={r} label={"reason: " + r}><Frame><Pop kind="failed" reason={r} profile={r === "profile_missing" ? "host-old" : WS.profile} /></Frame></Labelled>))}
        </View>
        <View name="remote-row-popup-languages" label="Every language — connecting, the longest reason and held">
          {row(LANGS.flatMap((lang) => [
            <Labelled key={lang + "c"} label={lang + " · connecting"}><Frame><Pop lang={lang} kind="connecting" /></Frame></Labelled>,
            <Labelled key={lang + "f"} label={lang + " · failed · chain"}><Frame><Pop lang={lang} kind="failed" reason="chain" /></Frame></Labelled>,
            <Labelled key={lang + "h"} label={lang + " · held"}><Frame><Pop lang={lang} kind="held" /></Frame></Labelled>,
          ]))}
        </View>
        <View name="remote-row-popup-narrow" label="Narrow workspace — the popup takes the width less space-md each side">
          <RemoteWorkspaceContent width="var(--tasty-size-320)" height="var(--tasty-size-288)"><Pop kind="closed" remote="release-pipeline-watch-eu-west" /></RemoteWorkspaceContent>
        </View>
      </Views>
      <Meta
        specs={[["ground", "the workspace content area in bg-app — no tab bar, no pane, no scrim"], ["popup", "Workspace-scope, centred in the content area · 360 wide, at most the area less space-md each side · no title bar, no ×, no drag"], ["frame", "bg-panel · 1px border-frame, the popup frame outline · radius · shadow-popover (no scrim under it) · the app's shared popup shell draws this edge already (border_frame): over the last screen the same shell takes shadow-modal"], ["inset · gaps", "space-md all round and between blocks · space-xs between the two fields"], ["head", "remote glyph 16 in accent-remote-raised + the row name, body semibold, end-elided"], ["fields", "Profile / Remote workspace — caption labels text-muted · values mono caption text-secondary, end-elided"], ["state block", "title body semibold text-primary + body text-secondary · warning glyph 14 (accent-warning-glyph) only for failed, timed out and closed"], ["remote workspace missing", <>a connect that finds the remote workspace gone, after a restart too (opened, on screen, popup or row menu Connect) · not Connection failed: the closed form, as over the last screen · warning glyph · title <code>remote.row.popup.closed_title</code> · body <code>remote.row.reason.workspace_missing</code> · Connect disabled in its place, no Spinner, label unchanged · row word not connected · an agent's request to use the row is refused (remote_workspace_missing) · Close locally removes the row</>], ["remote disconnected", <>the remote Tasty force-detached this row's own first attempt in this run, before it had a screen · no glyph · title <code>remote.row.popup.user_title</code> · body <code>remote.row.popup.server_body</code> · Connect enabled · shadow-popover, no scrim · row mark the plain disconnected word · not the user body: the user did not disconnect it</>], ["held", <>the row is held by its remote workspace's force-detach mark and lost no connection of its own: another saved row of the same remote workspace was force-detached in this run, or any of them after a restart while the saved mark is still there (it is saved for the remote workspace, and an explicit connect of any of its rows clears it, so after the next restart no row is held and they connect as L4 says) · no glyph · title <code>remote.row.popup.idle_title</code> · body <code>remote.row.popup.held_body</code> (new) · Connect enabled · shadow-popover, no scrim · row mark the not connected word, no warning mark · not Disconnected: this row was never disconnected · not the user body or <code>server_body</code>: both say this workspace was disconnected, which is false for a row that never connected · not the bare Not connected: that one connects once on screen, this one waits for the user</>], ["force detach: app today", <>tasty 580c8d1ee0 → target, an app change · first attempt cut before a screen: idle kind, no body, Connect → remote disconnected (<code>user_title</code>, <code>server_body</code>, Connect) · after a restart, and other rows of the same remote workspace with no last screen: idle kind, no body, Connect → held (<code>idle_title</code>, <code>held_body</code>, Connect) · another row of the same remote workspace with a last screen (connected or reconnecting when the other row was force-detached; the hold stops its reconnecting): user kind, <code>user_body_stay</code>, Reconnect → held over the last screen (<code>user_title</code>, <code>held_body</code>, Reconnect, Dropped while running) · over the last screen: user kind, <code>user_body_stay</code>, Reconnect → remote disconnected with Reconnect (Dropped while running) · lang has neither <code>server_body</code> nor <code>held_body</code> · cause: the force-detach path also puts the row in the user-disconnected set, and the popup reads one combined blocked flag, so a force detach cannot be told from the user's own Disconnect · the target order (closed elsewhere, the user's own Disconnect, remote disconnected, held) needs a mark that only the user's Disconnect sets, apart from the force-detach mark and the target hold</>], ["held until", "the user connects that row: popup Connect, row menu Connect, an agent's explicit connect request, picking the same remote workspace in the remote browser · row by row: connecting one does not free the others · a connection that succeeds on its own does not free it · saved across a restart only until the first explicit connect of any row of that remote workspace: that connect frees its row and clears the saved mark, so the other rows stay held for this run only · the mark goes for every row when the last saved row of that remote workspace is removed · order when more than one applies: closed elsewhere, then the user's own Disconnect, then remote disconnected, then held"], ["on screen", "the active workspace of an open window · the popup shows there on its own, no hover · a closed (parked) window shows none"], ["connects when", "it is the active workspace of the focused window and nothing holds it, with or without a click: opened, back after a restart, its window focused, a neighbour closed (L4) · so the first screen there is Connecting… · a row held by a Disconnect (the user's or the remote Tasty's) is skipped · an agent's request on a row not connected yet starts connecting too (Row and rail, agent use)"], ["user disconnected before connecting", <>Disconnect while it is Connecting… (no screen in this run yet) · the bare workspace form, shadow-popover, no glyph · title <code>remote.row.popup.user_title</code> · body <code>remote.row.popup.user_body_stay</code> · Connect enabled · held as L1 says: not connected on screen, on opening or for an agent until the user connects it or an agent's explicit connect request · row mark the plain disconnected word, no warning mark · not Not connected: the row is held by the user's own Disconnect, and Not connected reads as a row that has not been tried and will connect once on screen · no new copy · app today (tasty 580c8d1ee0) → target: the app cancels the attempt and marks the row user-disconnected, but a row with no session and no failure is published not connected, so it shows the idle kind (<code>idle_title</code>, no body, Connect) and the sidebar word not connected → the user kind above and the disconnected word; an app change</>], ["not connected", <>title <code>remote.row.popup.idle_title</code>, no body, no glyph, Connect enabled · only while nothing holds the row and nothing is trying it: the active workspace of a window that is not focused (a restart that restores several windows) until that window is focused · after the window that started the row's first attempt was closed and the attempt was dropped: once that window is open again and the row is its active workspace, until the retry is handled (a retry handled before the popup's first frame shows Connecting… at once) · never after a failed attempt (Connection failed), a Disconnect (Disconnected) or a remote force detach (Disconnected or held)</>], ["action", "one primary sm button, right: Connect · while trying: disabled, Spinner 12, Connecting…"], ["close", "not in the popup — Close locally is in the row menu"], ["focus", "never moved: an agent that starts a connection changes the row mark only"]]}
        tokens={[{ tok: "--tasty-bg-panel", use: "popup", color: "var(--tasty-bg-panel)" }, { tok: "--tasty-border-frame", use: "popup edge", color: "var(--tasty-border-frame)" }, { tok: "--tasty-shadow-popover", use: "popup lift, no scrim" }, { tok: "--tasty-accent-remote-raised", use: "head glyph", color: "var(--tasty-accent-remote-raised)" }, { tok: "--tasty-accent-warning-glyph", use: "failed glyph", color: "var(--tasty-accent-warning-glyph)" }, { tok: "--tasty-text-muted", use: "field labels", color: "var(--tasty-text-muted)" }, { tok: "--tasty-text-secondary", use: "values, body", color: "var(--tasty-text-secondary)" }, { tok: "--tasty-size-360", use: "popup width" }]} />
      <Note>Copy keys are <code>remote.row.popup.*</code> and <code>remote.row.reason.*</code> in <code>ui_kits/terminal/overlays/remote_row_copy.js</code>, four languages each. <b>Connect</b> is for a row that has not connected in this run; a row that had a screen says <b>Reconnect</b>, the child graph's word (<code>child_graph.reconnect</code>), because it is the same action. No token was added.</Note>
      <Dont><b>Don't</b> put <b>Close locally</b> beside Connect. The popup is about the connection; a removal next to the main button turns a missed click into a lost row.</Dont>
    </Spec>
  );
}

// ── 2. Dropped while running: the last screen under the scrim ──
export function RemoteRowLastScreenSpec() {
  return (
    <Spec id="remote-row-popup-over-the-last-screen" title="Dropped while running — the last screen under a scrim, the same popup"
      when={<>Only a row that was connected <b>in this run</b> keeps its tab bar, panes and last screen (nothing is saved across a restart). When its connection drops the screen stays where it was, under the <b>scrim clipped to the workspace content area</b>, and the same popup sits on it with <span className="tok">shadow-modal</span>. Nothing reaches the remote while it is down: input, new tabs and splits do not get through (§4). The scrim also <b>takes the pointer</b> (user decision, R-58 Q1): the last screen is inert like anything under a scrim, so it cannot be selected, copied or scrolled, and links and the file handler picker do not answer under it. <b>Reconnecting</b> is Tasty retrying on its own for the set time (Settings › Remote attach › Keep reconnecting for): title <b>Connection lost</b>, the time in the body, the button disabled with <b>Reconnecting…</b>. When the time runs out it becomes <b>Reconnection timed out</b> with <b>Reconnect</b>. After the user's own <b>Disconnect</b> it is neutral, no warning glyph. When the <b>remote Tasty force-detaches</b> the row (its occupancy border button, <code>tasty remote detach</code>), it ends the same way: the same <b>Disconnected</b> title, no glyph, <b>Reconnect</b> enabled, and only the body says who ended it. It does not reconnect on its own, not when the row is opened again, not for an agent, not after a restart, until the user reconnects. The mark is saved with the remote workspace, so after a restart every row of it comes back held on the bare workspace (Not connected yet, above), until an explicit connect of any of its rows clears the saved mark. Another row of the same remote workspace that still has its last screen is held where it is: <b>Disconnected</b>, the held body and <b>Reconnect</b>, no glyph, and its reconnecting stops. A failed Reconnect shows the reason as on the bare workspace. When the remote workspace is <b>closed elsewhere</b> (another client, the remote Tasty itself) the row stays and the title says so, <b>Remote workspace closed</b>, over the workspace-missing reason: nothing failed, so it does not borrow Connection failed. A Reconnect that finds the remote workspace missing, or after a restart a connect that does, shows the same form with its button disabled: it could only fail again. Its <b>Reconnect stays, disabled</b>: the workspace is gone, so it could only fail, and an action that cannot succeed is shown disabled, not hidden. The reason right above it says why, so nothing else repeats it.</>}>
      <Stage variant="solo" style={{ padding: "var(--tasty-space-lg)", background: "var(--tasty-bg-app)" }}>
        <ThemePair render={() => col(<>
          <Labelled label="reconnecting — automatic, up to the set time"><Frame shape><Pop shape kind="reconnecting" /></Frame></Labelled>
          <Labelled label="disconnected — the time ran out"><Frame shape><Pop shape kind="gave_up" /></Frame></Labelled>
          <Labelled label="disconnected — the user chose Disconnect · stays so until Reconnect or an agent's explicit connect request"><Frame shape><Pop shape kind="user" /></Frame></Labelled>
          <Labelled label="disconnected — the remote Tasty force-detached this row · Reconnect"><Frame shape><Pop shape kind="server" /></Frame></Labelled>
          <Labelled label="held — another row of the same remote workspace was force-detached · reconnecting stops · Reconnect"><Frame shape><Pop shape kind="held" /></Frame></Labelled>
          <Labelled label="closed — the remote workspace is gone: another client or the remote Tasty closed it, or a Reconnect found it missing · Reconnect disabled"><Frame shape><Pop shape kind="closed" /></Frame></Labelled>
        </>)} />
      </Stage>
      <Views>
        <View name="remote-row-last-screen-languages" label="Every language — reconnecting, timed out, disconnected by the remote Tasty and closed elsewhere">
          {row(LANGS.flatMap((lang) => [
            <Labelled key={lang + "r"} label={lang + " · reconnecting"}><Frame shape><Pop shape lang={lang} kind="reconnecting" /></Frame></Labelled>,
            <Labelled key={lang + "g"} label={lang + " · timed out"}><Frame shape><Pop shape lang={lang} kind="gave_up" /></Frame></Labelled>,
            <Labelled key={lang + "s"} label={lang + " · disconnected by the remote Tasty"}><Frame shape><Pop shape lang={lang} kind="server" /></Frame></Labelled>,
            <Labelled key={lang + "c"} label={lang + " · closed elsewhere"}><Frame shape><Pop shape lang={lang} kind="closed" /></Frame></Labelled>,
          ]))}
        </View>
      </Views>
      <Meta
        specs={[["shown", "a row that was connected in this run and is not now — never after a restart"], ["last screen", "drawn as it was, no blur, no change to terminal content (0 ms) · inert, the general under-scrim rule (R-58 Q1)"], ["cover", "scrim-bg clipped to the workspace content area (tab bar and panes) — sidebar, status bar and other windows stay clear"], ["pointer", "the scrim takes it (user decision, R-58 Q1) · no selection, copy, scroll, link or picker on the last screen while the row is not connected, reconnecting included"], ["popup", "same as on the bare workspace · shadow-modal, because it is centred over a scrim"], ["reconnecting", "title Connection lost · body: the reconnect time in s · button disabled, Spinner 12, Reconnecting…"], ["timed out", "warning glyph · Reconnection timed out · how long it tried · Reconnect"], ["user disconnected", <>no glyph · title <code>remote.row.popup.user_title</code> · body <code>remote.row.popup.user_body_stay</code> · Reconnect enabled · stays disconnected in this run: opening the row again does not reconnect it (L1) · an agent's request to use it is refused with an error that says the user disconnected it, and the row mark stays disconnected · an agent's explicit connect request (<code>tasty remote connect</code>) connects it, as Reconnect does, and ends the mark</>], ["remote disconnected", <>the remote Tasty force-detached this row while it was connected (surface or workspace) · same place as user disconnected, the two never hold together, and the user's own Disconnect on it turns it into user · no glyph · title <code>remote.row.popup.user_title</code> · body <code>remote.row.popup.server_body</code> (new) · Reconnect enabled, the only way back (opening the row or an agent request does not reconnect it) · the mark is on the remote workspace (profile and remote workspace) and is saved across a restart until an explicit connect of any of its rows (held until, Not connected yet) · after a restart, and for the other rows of the same remote workspace with no last screen: the held form (Not connected yet) · drawn here over the last screen; a first attempt cut before a screen takes the bare workspace form with Connect · app today (tasty 580c8d1ee0) → target: over the last screen the user kind with <code>user_body_stay</code> and Reconnect, because the force-detach path also marks the row user-disconnected → this form; after a restart the idle kind with no body and Connect → held; an app change (Not connected yet, force detach: app today) · row mark the plain disconnected word, no warning mark · its own body, not <code>remote.row.popup.user_body_stay</code>: that body tells the user they disconnected it, which is false here, and the user needs to know the other side ended it before choosing to reconnect</>], ["held over the last screen", <>another saved row of the same remote workspace was force-detached while this row had its last screen (connected, reconnecting or timed out) · the hold stops its reconnecting · no glyph · title <code>remote.row.popup.user_title</code>, because this row did lose its connection · body <code>remote.row.popup.held_body</code>, because the user and this row did not end it and the body names who holds it · Reconnect enabled, the only way back, and it frees this row only · shadow-modal over the scrim · row mark the plain disconnected word, no warning mark · not the user body (false: the user did not disconnect it) · not <code>server_body</code> (this row was not the one detached) · not Not connected (it had a connection in this run) · app today (tasty 580c8d1ee0) → target: the user kind with <code>user_body_stay</code> and Reconnect, through the same combined blocked flag → this form; an app change</>], ["failed", "warning glyph · Connection failed · reason · Reconnect · every reason but workspace_missing, which is closed"], ["closed", <>the remote workspace is gone: another client or the remote Tasty closed it while the row was connected, or a Reconnect found it missing · the row stays (R-58 Q4) · warning glyph · <code>remote.row.popup.closed_title</code> (new) · body <code>remote.row.reason.workspace_missing</code> · Reconnect disabled, no Spinner, label unchanged · row word disconnected · the body is the reason, no tooltip or extra line · an agent's request to use the row is refused (remote_workspace_missing) · not kept across a restart: the row comes back not connected with Connect enabled, and a connect that finds the workspace still missing shows the same form on the bare workspace with Connect disabled (Not connected yet)</>], ["reconnect time 0", "no reconnecting state: the drop goes straight to timed out with 0 s"], ["links, picker", "not reached on a saved remote row that is not connected, so no form: no link tooltip, no picker host mark (Layouts › Path link on a mirror, Dialogs › File handler picker) · a link tooltip or picker open when the row drops (into reconnecting too) closes, and does not reopen when the row connects again (decided, Q1-a)"]]}
        tokens={[{ tok: "--tasty-scrim-bg", use: "cover over the last screen", color: "var(--tasty-scrim-bg)" }, { tok: "--tasty-shadow-modal", use: "popup over the scrim" }, { tok: "--tasty-accent-warning-glyph", use: "timed out, failed", color: "var(--tasty-accent-warning-glyph)" }]} />
      <Note>The status bar under the workspace stays live: on a focused mirror surface it keeps its read-only form, <i>reconnecting</i> while Tasty retries and <i>disconnected</i> once it stops (Layouts › Workspace status bar). An agent mirror made from the CLI or IPC does not reconnect (R-58 decision 23-4): no scrim and no popup, it is closed once it drops. Its only reconnecting is short and has no scrim: attaching again after a resync, and the span between the drop and the cleanup; there the read-only marks take the reconnecting form.</Note>
      <Note><b>Toasts (R-58 §3-8).</b> A saved remote row shows <b>no connection toasts</b>: not <code>attach.toast.mirror_disconnected</code> (“…The mirror workspace has been closed.”, wrong for a row that stays), not <code>attach.toast.mirror_reconnecting</code>, not <code>attach.toast.mirror_reconnected</code>, not <code>attach.toast.mirror_reconnect_giveup</code> (its “switch away and back” advice does not apply). The row mark tells it whether or not the row is active, and the popup tells it while the row is on screen; a toast would say the same thing a third time and then be gone. An agent mirror does not reconnect, so it gets none of the three reconnect toasts; when it drops it only shows <code>attach.toast.mirror_disconnected</code>, the notice that it was closed.</Note>
      <Do><b>Do</b> keep the last screen readable under the scrim. It tells you which workspace this was and where it stopped, and it comes back as it is when Reconnect succeeds.</Do>
      <Dont><b>Don't</b> animate the cover or the screen under it. The only motion is the button's spinner while Tasty is trying.</Dont>
    </Spec>
  );
}

// ── 3. Row and rail marks ──
const ROWS = [
  ["connected", { remoteState: "connected", status: "running", running: 2 }],
  ["connecting", { remoteState: "connecting" }],
  ["reconnecting", { remoteState: "reconnecting", status: "running", running: 2 }],
  ["disconnected (last screen kept)", { remoteState: "disconnected" }],
  ["not connected (after a restart)", { remoteState: "not_connected" }],
  ["disconnected + reason", { remoteState: "disconnected", remoteReason: "occupied" }],
  ["not connected + reason", { remoteState: "not_connected", remoteReason: "profile_missing", remoteProfile: "host-old" }],
];
function Rows({ active, lang }) {
  return (
    <div style={{ width: "var(--tasty-size-240)", display: "flex", flexDirection: "column", background: "var(--tasty-bg-sidebar)", border: "var(--tasty-border-width) solid var(--tasty-border-frame)", borderRadius: "var(--tasty-radius)", overflow: "hidden" }}>
      {ROWS.map(([label, o]) => (
        <div key={label} title={label}>
          <WorkspaceRow ws={{ id: label, name: "tasty-core", mirror: true, status: "idle", remoteProfile: "host", remoteName: "tasty-core", ...o }} active={active} lang={lang} />
        </div>
      ))}
    </div>
  );
}
function RailAvatar({ o, active }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "var(--tasty-space-xs)", width: "var(--tasty-size-64)" }}>
      <div title={remoteRowTip({ name: "tasty-core", remoteProfile: "host", remoteName: "tasty-core", ...o[1] })} style={{ position: "relative", width: "var(--tasty-size-36)", height: "var(--tasty-size-36)", display: "inline-flex", alignItems: "center", justifyContent: "center",
        borderRadius: "var(--tasty-radius)", background: active ? "var(--tasty-overlay-active)" : "transparent",
        fontFamily: "var(--tasty-font-mono)", fontWeight: "var(--tasty-font-weight-bold)", fontSize: "var(--tasty-font-size-body)", color: active ? "var(--tasty-accent-primary-raised)" : "var(--tasty-text-muted)" }}>
        T
        <RemoteRailMarks state={o[1].remoteState} warn={!!o[1].remoteReason} />
      </div>
      <span style={{ ...cap, textAlign: "center" }}>{o[0]}</span>
    </div>
  );
}
export function RemoteRowMarksSpec() {
  return (
    <Spec id="remote-row-marks-sidebar-and-rail" title="Row and rail — the connection state at a glance"
      when={<>The row says how the connection stands whether or not it is active; it never moves focus. The <b>REMOTE</b> tag stays the identity. <b>Connected</b> is today's tag in the remote hue. Every other state follows the status bar's read-only form: the tag turns <b>neutral</b> and a <b>status word</b> follows it — <i>connecting</i>, <i>reconnecting</i>, <i>disconnected</i> (the last screen is kept), <i>not connected</i> (nothing since Tasty started). While Tasty is trying (connecting, reconnecting) the dot slot shows the <b>LNB loading spinner</b>, the one Attaching… already uses; off the live state the dot falls to idle and the running count goes, because a status from a dropped connection is stale. A failed attempt adds the <b>warning mark</b> after the name — the auto-attach refusal mark, same glyph, slot and token — with the reason in the tooltip. Disconnected and failed are told apart by that mark: no mark is a plain end, a mark is something to read. The rail keeps the same four corners: the remote chip at bottom right turns neutral off the live state, the loading ring surrounds the initial while trying, the warning chip takes the top left.</>}>
      <Stage variant="solo" style={{ padding: "var(--tasty-space-lg)", background: "var(--tasty-bg-app)" }}>
        <ThemePair render={() => row(<>
          <Labelled label="inactive rows"><Rows /></Labelled>
          <Labelled label="active rows"><Rows active /></Labelled>
          <Labelled label="rail">
            <div style={{ display: "flex", flexWrap: "wrap", gap: "var(--tasty-space-sm)", width: "var(--tasty-size-288)", padding: "var(--tasty-space-sm)", background: "var(--tasty-bg-sidebar)", borderRadius: "var(--tasty-radius)" }}>
              {ROWS.map((o) => <RailAvatar key={o[0]} o={o} />)}
            </div>
          </Labelled>
        </>)} />
      </Stage>
      <Views>
        <View name="remote-row-marks-languages" label="Status words — every language">
          {row(LANGS.map((lang) => <Labelled key={lang} label={lang}><Rows lang={lang} /></Labelled>))}
        </View>
      </Views>
      <Meta
        specs={[["connected", "REMOTE info Tag in the remote hue + the workspace's own dot and running count — unchanged"], ["off the live state", "REMOTE default Tag (tag-fg on its own fill) + status word: font-label caption, text-muted (text-on-active on the active row), end-elided"], ["words", "connecting · reconnecting (status_bar.remote_reconnecting) · disconnected (status_bar.remote_disconnected) · not connected"], ["dot slot", "trying: Spinner 14 (the LNB loading spinner) · otherwise not live: idle dot · running count hidden"], ["reason", "alertTriangle 14 in attach-refusal-glyph after the name, space-sm before it · tooltip: what it is, profile → remote workspace, the reason"], ["tooltip", "attach.mirror_workspace · profile → remote workspace (mono in the app) · the status word or the reason"], ["rail BR chip", "live: unchanged · not live: 1px border-control, glyph-dim remote glyph on workspace-mirror-chip-bg"], ["rail trying", "the 28 loading ring around the initial; corner chips draw above it"], ["rail TL chip", "the refusal chip — alertTriangle 8 on bg-sidebar"], ["agent use (N2)", "the row goes to connecting and back; focus stays where it is · a row not connected yet: the request starts connecting and waits up to 35 s, then answers with the result; a failure or refusal is an error with its reason (L2) · list queries do not connect a row, its mark stays as it is (L3) · a row the user disconnected: refused, mark unchanged, until an explicit connect request (L1)"], ["new tokens", "none — tag-fg, text-muted, border-control and glyph-dim are existing roles on bg-sidebar (glyph-dim 3.59 · 4.64, border-control 3.59 · 3.58)"]]}
        tokens={[{ tok: "--tasty-tag-info-fg", use: "REMOTE, connected", color: "var(--tasty-tag-info-fg)" }, { tok: "--tasty-tag-fg", use: "REMOTE, not live", color: "var(--tasty-tag-fg)" }, { tok: "--tasty-text-muted", use: "status word", color: "var(--tasty-text-muted)" }, { tok: "--tasty-attach-refusal-glyph", use: "reason mark", color: "var(--tasty-attach-refusal-glyph)" }, { tok: "--tasty-border-control", use: "rail chip edge, not live", color: "var(--tasty-border-control)" }, { tok: "--tasty-glyph-dim", use: "rail chip glyph, not live", color: "var(--tasty-glyph-dim)" }]} />
      <Note>The auto-attach refusal <b>banner</b> does not show on a saved remote row; the popup carries the reason. The row mark and rail chip are the refusal's, so a mapped workspace and a saved remote row warn in the same place.</Note>
      <Note><b>Glyph.</b> The REMOTE tag and the rail chip now draw the <code>remote</code> glyph through <code>Icon</code>, at the icon set's 2px stroke. They used to inline the same path at a 2.4 stroke. That is deliberate: the rules allow glyphs only through <code>Icon</code>, and the set has one stroke. At 10 and 8 px the thinner line is the only visible change; size, colour and position are unchanged.</Note>
      <Dont><b>Don't</b> drop the REMOTE tag when the connection is down. It is what the row is; the word next to it says how it stands.</Dont>
    </Spec>
  );
}
